package pe.edu.upeu.inscripcion.client;
import org.springframework.stereotype.Component;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.web.client.*;import org.springframework.web.server.ResponseStatusException;import java.util.*;import java.math.BigDecimal;
@Component public class CertificadoContextoClient {
 private final RestClient client;
 @Value("${kido.certificados.usuarios-url:http://kido-usuario-ms:8080}") private String usuarios;
 @Value("${kido.certificados.catalogo-url:http://kido-curso-1:8080}") private String catalogo;
 public CertificadoContextoClient(){var http=new org.springframework.http.client.SimpleClientHttpRequestFactory();http.setConnectTimeout(java.time.Duration.ofSeconds(3));http.setReadTimeout(java.time.Duration.ofSeconds(8));client=RestClient.builder().requestFactory(http).build();}
 public CertificadoContextoClient(RestClient client){this.client=client;}
 public record Cuenta(Long id,String nombre,List<String> roles){public boolean admin(){return roles.contains("ADMIN");}public boolean docente(){return roles.contains("DOCENTE");}}
 @com.fasterxml.jackson.annotation.JsonIgnoreProperties(ignoreUnknown=true)
 public record Curso(Long id,String titulo,String tipo,String estado,Long docenteId,List<Long> leccionIds,Integer progresoMinimo,Integer asistenciaMinima,boolean certificadoHabilitado,BigDecimal certificadoCosto){}
 @SuppressWarnings("unchecked") public Cuenta cuenta(String auth){if(auth==null||!auth.startsWith("Bearer "))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED);Map<String,Object> p;try{p=client.get().uri(usuarios+"/api/v1/usuarios/me").header(HttpHeaders.AUTHORIZATION,auth).retrieve().body(Map.class);}catch(HttpClientErrorException e){throw new ResponseStatusException(e.getStatusCode().value()==403?HttpStatus.FORBIDDEN:HttpStatus.UNAUTHORIZED);}if(p==null||!(p.get("id") instanceof Number id))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED);String nombre=(Objects.toString(p.get("nombres"),"")+" "+Objects.toString(p.get("apellidos"),"")).strip();var roles=p.get("roles") instanceof List<?> r?r.stream().map(String::valueOf).toList():List.<String>of();return new Cuenta(id.longValue(),nombre,roles);}
 public void propietario(Long id,String auth){var c=cuenta(auth);if(!c.admin()&&!Objects.equals(c.id(),id))throw new ResponseStatusException(HttpStatus.FORBIDDEN);}
 public void admin(String auth){if(!cuenta(auth).admin())throw new ResponseStatusException(HttpStatus.FORBIDDEN);}
 public Curso curso(Long id){var c=client.get().uri(catalogo+"/internal/v1/cursos/{id}/resumen-compra",id).retrieve().body(Curso.class);if(c==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND);return c;}
 public void docenteCurso(Long id,String auth){var c=cuenta(auth);if(c.admin())return;if(!c.docente()||!Objects.equals(c.id(),curso(id).docenteId()))throw new ResponseStatusException(HttpStatus.FORBIDDEN);}
 @SuppressWarnings("unchecked") public String alumno(Long id,String auth){var c=cuenta(auth);if(Objects.equals(c.id(),id)){if(c.nombre().isBlank())throw new IllegalStateException("Completa tus nombres y apellidos antes de descargar el certificado");return c.nombre();}if(!c.admin())throw new ResponseStatusException(HttpStatus.FORBIDDEN);List<Map<String,Object>> personas=client.get().uri(usuarios+"/api/v1/usuarios/admin/cuentas").header(HttpHeaders.AUTHORIZATION,auth).retrieve().body(List.class);if(personas!=null)for(var p:personas)if(p.get("perfilId") instanceof Number perfil&&perfil.longValue()==id.longValue())return (Objects.toString(p.get("nombres"),"")+" "+Objects.toString(p.get("apellidos"),"")).strip();throw new IllegalStateException("El perfil del estudiante no tiene nombres disponibles");}
}
